const exec = $json.execution || {};
const err  = exec.error || {};
const nodeName = (err.node && err.node.name) || exec.lastNodeExecuted || 'desconocido';
const errorMsg = err.message || 'Error desconocido';

const phaseMap = {
  'HTTP - Download':              { phase: 'download',   fix: null },
  'HTTP - Transcribe':            { phase: 'transcribe', fix: 'delete_transcript' },
  'HTTP - Cut':                   { phase: 'cut',        fix: 'delete_edited' },
  'HTTP - HTML':                  { phase: 'html',       fix: 'delete_beats' },
  'HTTP - Render':                { phase: 'render',     fix: 'delete_renders' },
  'HTTP - OpenAI Beats':          { phase: 'ai_beats',   fix: null },
  'HTTP - OpenAI HTML':           { phase: 'ai_beats',   fix: null },
  'Code - Parsear Beats':         { phase: 'ai_beats',   fix: null },
  'Code - Preparar HTML Prompt':  { phase: 'ai_beats',   fix: null },
};
const mapped = phaseMap[nodeName] || { phase: 'unknown', fix: null };

return [{ json: {
  phase:         mapped.phase,
  suggested_fix: mapped.fix,
  error_msg:     String(errorMsg).slice(0, 800),
  node_name:     nodeName,
  workflow_url:  exec.url || 'https://n8n.esencialabs.co'
}}];

const ctx     = $('Code - Extraer Contexto').item.json;
const active  = $('HTTP - Get Active Project').item.json;
const logData = $('HTTP - Get Pipeline Log').item.json;
const project = active.project || 'unknown';
const lastLog = (logData.log || '').split('\n').slice(-40).join('\n');

const systemPrompt = `You are a diagnostic AI for a video pipeline on Ubuntu 24.04.
The pipeline uses Puppeteer+Chrome, FFmpeg (ProRes 4444), Node.js, rclone, and Whisper API.

AVAILABLE FIX ACTIONS (return exactly one or null):
- "delete_renders" — delete corrupt .mov files (Chrome crash, moov atom, ENOENT on .mov)
- "delete_transcript" — delete audio_whisper.mp3 + transcript.json (Whisper API failure)
- "delete_edited" — delete edited video (ffmpeg cut failure)
- "delete_beats" — delete beats_with_paths.json (HTML generation failure)
- "kill_ffmpeg" — kill hanging ffmpeg (timeout / ETIMEDOUT)
- "reset_project" — full composition dir clean (unknown/unrecoverable)
- null — cannot auto-fix; needs human (rclone auth error, OpenAI quota, etc.)

Always respond with JSON only: {"fix_action": "...", "explanation": "..."}`;

const userMsg = `FAILED PHASE: ${ctx.phase}\nFAILED NODE: ${ctx.node_name}\nPROJECT: ${project}\nERROR: ${ctx.error_msg}\n\nLAST LOG LINES:\n${lastLog}`;

return [{ json: {
  system_prompt: systemPrompt,
  user_message: userMsg,
  project,
  phase: ctx.phase,
  suggested_fix: ctx.suggested_fix,
  error_msg: ctx.error_msg,
  workflow_url: ctx.workflow_url
}}];

let content = $json.choices?.[0]?.message?.content || '{"fix_action":null,"explanation":"OpenAI no disponible"}';
content = content.replace(/```json\s*/g,'').replace(/```\s*/g,'').trim();
let parsed;
try { parsed = JSON.parse(content); }
catch(e) { parsed = { fix_action: null, explanation: 'JSON parse error: ' + content.slice(0,100) }; }

const diagCtx = $('Code - Build Diagnose Prompt').item.json;
return [{ json: {
  fix_action:  parsed.fix_action  || diagCtx.suggested_fix || null,
  explanation: parsed.explanation || '',
  project:     diagCtx.project,
  phase:       diagCtx.phase,
  error_msg:   diagCtx.error_msg,
  workflow_url: diagCtx.workflow_url,
  should_fix:  !!(parsed.fix_action || diagCtx.suggested_fix)
}}];

const r = $json;
const fixCtx = $('Code - Parse Fix Action').item.json;
const success = r.ok === true && r.error === undefined;
return [{ json: {
  success,
  project: fixCtx.project,
  phase: fixCtx.phase,
  fix_action: fixCtx.fix_action,
  explanation: fixCtx.explanation,
  error_msg: r.error || fixCtx.error_msg,
  workflow_url: fixCtx.workflow_url
}}];
